 import unittest
from candidate import pairs_sum_to_zero

class TestPairsSumToZero(unittest.TestCase):
    def test_pairs_sum_to_zero_normalcase(self):
        self.assertTrue(pairs_sum_to_zero([2, 4, -5, 3, 5, 7]))

    def test_pairs_sum_to_zero_empty_list(self):
        self.assertFalse(pairs_sum_to_zero([]))

    def test_pairs_sum_to_zero_single_element(self):
        self.assertFalse(pairs_sum_to_zero([1]))

    def test_pairs_sum_to_zero_single_pair(self):
        self.assertTrue(pairs_sum_to_zero([0, 0]))

    def test_pairs_sum_to_zero_one_negative(self):
        self.assertFalse(pairs_sum_to_zero([-1, 1]))

    def test_pairs_sum_to_zero_multiple_pairs(self):
        self.assertTrue(pairs_sum_to_zero([1, -1, 0, 2]))

    def test_pairs_sum_to_zero_duplicates(self):
        self.assertFalse(pairs_sum_to_zero([1, 1, 0]))

    def test_pairs_sum_to_zero_only_negative(self):
        self.assertFalse(pairs_sum_to_zero([-1, -2]))

if __name__ == '__main__':
    unittest.main()
